INSERT INTO public.desempeno_jefes_areas (anio, codigo, nombre, es_comun, empleado_id, aporte, reglas, pendientes, orden) VALUES (2027, 'COMUN', 'Evaluación común (40%)', true, NULL, 'Mide cómo trabaja cada jefe, igual para los 8. Nota total = KPIs del área × 60% + competencias × 40%. Trimestres con encuesta (junio y diciembre): las 4 competencias valen 10% cada una. Trimestres sin encuesta (marzo y septiembre): el 40% se reparte entre autogestión y documentación, 20% cada una.', 'Cada competencia se mide con varias preguntas calificadas de 1 a 5; el indicador es el promedio ÷ 5 × 100. Escala por frecuencia: 5 Siempre, 4 Casi siempre, 3 A veces o Muchas veces, 2 Pocas veces, 1 Nunca; donde hay dato, la calificación sale del dato. Un 1 o un 5 solo se pone con un caso concreto anotado (fecha y qué pasó). Liderazgo lo califica el equipo del jefe y trabajo en equipo los otros jefes, de forma confidencial (el jefe solo ve el promedio). Autogestión la califica gerencia, con autocalificación previa del jefe. Documentación se mide en visita sorpresa de RRHH. Conducta (respeto, honestidad, reglamento interno) no suma puntos; una falta grave documentada deja el 40% del trimestre en cero, además del proceso con RRHH.', 'Formato de minuta semanal por jefe. Formatos de las encuestas de liderazgo y trabajo en equipo, y de la visita de documentación. Lista del equipo de cada jefe y de qué jefes califican a cada uno. Quién encuesta al equipo de RRHH. Listas de documentos obligatorios y procedimientos por área (enero). Acordar con RRHH dónde se guardan los casos anotados.', 0) ON CONFLICT (anio, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_areas (anio, codigo, nombre, es_comun, empleado_id, aporte, reglas, pendientes, orden) VALUES (2027, 'COM', 'Comercial', false, '88257caf-5979-414e-83a2-efa5b751cc60', 'Vender más, aumentar las ventas a cliente final para depender menos de los distribuidores, y legalizar las ventas (todo facturado).', 'Descuentos por encima del tope requieren aprobación de gerencia. No vender directo por debajo del precio del distribuidor.', 'Ventas facturadas 2026 por mes. Clasificación de ventas 2026 por canal (distribuidor o cliente final). Registro de leads desde el 1 de enero de 2027.', 1) ON CONFLICT (anio, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_areas (anio, codigo, nombre, es_comun, empleado_id, aporte, reglas, pendientes, orden) VALUES (2027, 'MEC', 'Mecanizados', false, 'cd313307-19cd-4fab-bfd3-4445f59c7e30', 'Entregar a Ensamble las piezas a tiempo y completas, gastar menos insumos y herramientas por pieza, y establecer los tiempos estándar de mecanizado para medir productividad y costear la mano de obra.', 'Toda salida de insumos para Mecanizados pasa por el ERP. Cuidado diario de las máquinas (limpieza, lubricación, reporte temprano de daños) se evalúa en autogestión. Calidad: desde marzo se registran no conformidades de Mecanizados en el ERP; mientras tanto Ensamble anota las piezas que recibe malas. Se revisa en julio si entra como KPI. Aluminio (también a cargo de William) queda por fuera de esta evaluación por ahora.', 'Cambios en el ERP antes de enero: hora de inicio y fin en el registro de mecanizado, fecha pedida en los paquetes y no conformidades para Mecanizados. Costear los insumos de Mecanizados que están en $0. Línea base de costo de insumos por pieza oct-dic 2026.', 2) ON CONFLICT (anio, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_areas (anio, codigo, nombre, es_comun, empleado_id, aporte, reglas, pendientes, orden) VALUES (2027, 'FUN', 'Fundición de hierro', false, 'a544afb9-755e-45dd-8c1b-6375b8312447', 'Perder menos hierro en cada fundida y sacar menos piezas con defecto, para bajar el costo de las piezas que van a Mecanizados y a Ensamble.', 'A Julián solo se le mide lo que controla. Lo que la fundición necesite de diseño (modelos, moldes, alimentadores) lo pide por escrito y entra al plan de proyectos de Innovación con fecha; Julián valida lo entregado. Toda pieza con defecto se registra en el ERP con su motivo. Comportamiento y trato se evalúan en el 40% común, con hechos documentados.', 'Línea base de merma y de piezas no conformes (se mide desde diciembre 2026). Confirmar que las no conformidades se registran todos los días. Mostrar merma, piezas no conformes y su motivo en el inicio de Fundición en el ERP. Opción: costeo de piezas fundidas (costo por kilo) como proyecto de Julián.', 3) ON CONFLICT (anio, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_areas (anio, codigo, nombre, es_comun, empleado_id, aporte, reglas, pendientes, orden) VALUES (2027, 'ENS', 'Ensamble, soldadura y armado', false, '1ff00101-19ed-41d1-afff-3cee46ea1ef3', 'Entregar las máquinas en la fecha prometida a ventas y sin defectos, para cumplirle al cliente y no perder ventas.', 'Lo que no está en el ERP no existe: si no se registra, el KPI sale sin dato y cuenta como incumplido. Planillas de producción en la app a más tardar el día hábil siguiente. Una OF retrasada por falta de material no cuenta en contra solo si el faltante quedó registrado en el ERP ese mismo día. Personal: se pide por escrito a RRHH con anticipación. Reunión semanal de planeación con Comercial y Logística para prometer fechas según la capacidad real. Ninguna máquina se despacha sin su revisión de calidad registrada. El % de OF a tiempo se revisa en la reunión semanal con todos los jefes de producción.', 'Cambios en el ERP, aplazados por gerencia hasta cerrar los KPIs: revisión de calidad por máquina y registro de faltantes de material ligado a la OF. Hoy hay 0 planillas y 0 números de máquina en el ERP. Definir la lista de revisión de calidad por tipo de máquina. Ferretería: cargarla al ERP y que el custodio sea Almacén (no es KPI de Ensamble).', 4) ON CONFLICT (anio, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_areas (anio, codigo, nombre, es_comun, empleado_id, aporte, reglas, pendientes, orden) VALUES (2027, 'LOG', 'Compras y logística', false, 'b70446e8-dcf6-480f-9633-3c98984ee5cd', 'Abastecer a tiempo y al menor costo total, sin depender de un solo proveedor en lo crítico, y despachar sin errores para cuidar al cliente final.', 'Mínimo dos cotizaciones para compras sobre el monto que defina gerencia. La lista de referencias críticas con proveedor único la aprueba gerencia. Lead time, compras urgentes y cumplimiento de proveedores se revisan en el comité mensual como seguimiento. Compromiso: lista de precios de referencia de las 20 materias primas de mayor valor a marzo 2027, para medir ahorro en compras desde el segundo semestre.', 'Línea base real de lead time oct-dic 2026 desde el ERP. Lista de referencias con proveedor único. Definición de error de despacho y casilla para registrarlo en el ERP. Precios de referencia para medir ahorro.', 5) ON CONFLICT (anio, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_areas (anio, codigo, nombre, es_comun, empleado_id, aporte, reglas, pendientes, orden) VALUES (2027, 'IYD', 'Innovación y diseño', false, '5fe7376a-1c10-4272-b44e-349fe1bc9620', 'Entregar proyectos de mejora y diseño con ahorro medible para la empresa, y mantener produciendo el centro de mecanizado a su cargo.', 'Cargo por escrito: Innovación y Diseño + centro de mecanizado (no mantenimiento). Cambiar su rol en el ERP (hoy figura como Jefe de Mantenimiento). Solo interviene en mantenimientos con orden de trabajo aprobada por gerencia en el ERP; el tiempo en mantenimientos sin orden no excusa incumplimientos. Plan de proyectos aprobado en enero: 1 proyecto por trimestre, cada uno con entregable y ahorro estimado. Reunión semanal de seguimiento con minuta en el primer trimestre; el cumplimiento de compromisos se evalúa en autogestión (40%). Documentar con RRHH.', 'Entregarle por escrito cargo, KPIs y reglas. Cambio de rol en el ERP. Plan de proyectos 2027 aprobado en enero. Campo de hora de inicio y fin en el ERP para medir el centro de mecanizado. Confirmar con RRHH el tipo de contrato.', 6) ON CONFLICT (anio, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_areas (anio, codigo, nombre, es_comun, empleado_id, aporte, reglas, pendientes, orden) VALUES (2027, 'RRHH', 'Recursos humanos', false, '9e061435-497f-4415-8fde-b5e05dc98fc8', 'Retener al personal (de 37 ingresos en 2026 solo siguen 13), evaluar a todos contra su perfil de cargo y bajar el costo de la rotación: selección, inducción, curva de aprendizaje y reprocesos.', 'Exámenes médicos ocupacionales vigentes y cartas de renovación enviadas con 30 días de anticipación: siempre 100% (obligación legal, no suma puntos). Revisión del esquema de contratistas con abogado laboral antes de enero (riesgo de contrato realidad). La lista de procesos críticos la aprueba gerencia. Compromisos del cronograma: 2 espacios de liderazgo, reinducción en marzo, contratos en el ERP a febrero, informe trimestral a gerencia. Evaluación del piloto de incentivos en julio con costo vs. ahorro en retiros.', 'Rotación 2026 en números (retiros y promedio de colaboradores). Retención a 90 días de 2026. Formato de evaluación por área (feb-may 2027). Contratos y fechas de ingreso cargados al ERP (feb 2027).', 7) ON CONFLICT (anio, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_areas (anio, codigo, nombre, es_comun, empleado_id, aporte, reglas, pendientes, orden) VALUES (2027, 'CON', 'Contabilidad', false, '168a2870-5dc8-412f-a4d4-e35183162807', 'Entregar a gerencia cifras confiables y a tiempo de las dos empresas (Feisen y FC) para tomar decisiones y medir los KPIs de las demás áreas.', 'Declaraciones de impuestos a tiempo y sin sanciones: siempre 100%. Lorena responde por que la contabilidad externa cumpla. El costeo de máquinas queda en otras áreas (decisión de gerencia).', 'Correcciones pedidas a la contabilidad externa el 13/11/2026: compras sin centro de costo, costo de ventas mensual irregular, criterio materia prima vs. insumos, diferencia de junio ($36,2 M), proveedor duplicado.', 8) ON CONFLICT (anio, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'comercial-ventas', 'kpi', 'Crecimiento en ventas', '(Ventas acumuladas 2027 a la fecha − mismo período 2026) ÷ mismo período 2026. Ventas de Construequipos (máquinas, repuestos y mantenimientos, Siigo + Odoo), netas de devoluciones', 40, NULL, 'Mensual', '2026 proyectado: $8.323 M (ene-oct real $6.786 M × 1,23). 2025 real: $7.049 M', '+12% → $9.322 M', '+7% → $8.906 M', 'si', 'EEFF 2026 (Excel de gerencia) hasta septiembre; desde octubre, pantalla EEFF del ERP (Odoo Feisen + Odoo FC)', 'Reemplazar la proyección por el cierre real de 2026 en enero', NULL, 'borrador', 'Mínimo = crecimiento de la economía (~2%) + inflación esperada 2027 (~4,5-5,5%). Meta = mínimo + ~5 puntos de venta directa y marketing. Se mide acumulado porque feb-abr 2026 fueron atípicos (+40% a +67%). Ventas externas de fundición quedan por fuera.', 1 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'COM' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'comercial-cliente-final', 'kpi', '% de ventas a cliente final', 'Ventas facturadas a cliente final ÷ ventas facturadas totales', 35, NULL, 'Mensual', NULL, NULL, NULL, 'parcial', 'Facturación electrónica, con cada cliente marcado como distribuidor o cliente final', 'Clasificar los clientes de 2026 por canal', NULL, 'borrador', 'Mide la menor dependencia de los distribuidores.', 2 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'COM' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'comercial-leads', 'kpi', 'Conversión de leads', 'Leads de cliente final que compraron ÷ leads de cliente final que llegaron', 25, NULL, 'Mensual', NULL, 'Se fija en abril de 2027', NULL, 'no', 'Registro de leads (fecha, nombre, de dónde llegó, si compró, valor)', 'Crear el registro de leads y llenarlo desde el 1 de enero de 2027', NULL, 'borrador', 'Mide si el marketing se convierte en ventas. Primer trimestre solo se mide.', 3 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'COM' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'comun-autogestion', 'competencia', 'Autogestión y cumplimiento', 'Promedio de 5 preguntas calificadas de 1 a 5, ÷ 5 × 100. (1) ¿Cumple los compromisos en la fecha acordada? (2) ¿Avisa los problemas antes de que se vuelvan urgentes? (3) ¿Trae soluciones y no solo problemas? (4) ¿Organiza su trabajo y el de su equipo sin que se lo pidan? (5) ¿Llega preparado a las reuniones?', 25, 50, 'Trimestral', 'Primera evaluación: marzo 2027', '≥ 80% (promedio 4)', '≥ 60% (promedio 3)', 'parcial', 'Pregunta 1: minuta semanal (% de compromisos cumplidos a tiempo). Preguntas 2 a 5: casos anotados en el trimestre', 'Formato de minuta semanal por jefe', 'Gerencia, con autocalificación previa del jefe', 'borrador', 'Pregunta 1 por dato: 5 = 95% o más; 4 = 85-94%; 3 = 70-84%; 2 = 50-69%; 1 = menos de 50%. Preguntas 2 a 5 por frecuencia: 5 Siempre (ningún caso en contra), 4 Casi siempre (uno o dos casos aislados), 3 Muchas veces (hay que recordarle con alguna frecuencia), 2 Pocas veces, 1 Nunca (hay que estar detrás de todo). Un 1 o un 5 en las preguntas 2 a 5 exige un caso anotado con fecha. El jefe se autocalifica primero y se compara en la reunión.', 1 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'COMUN' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'comun-documentacion', 'competencia', 'Documentación, ERP y procedimientos', 'Promedio de 6 preguntas calificadas de 1 a 5, ÷ 5 × 100. Archivo físico: (1) ¿Las carpetas están completas? (2) ¿Están al día y firmadas? (3) ¿Se encuentra rápido lo que se pide? ERP: (4) ¿Sus registros en el ERP están al día? (5) ¿Lo que registra es confiable? Procedimientos: (6) ¿El jefe y su equipo conocen y siguen los procedimientos?', 25, 50, 'Trimestral (visita sorpresa)', 'Primera revisión: marzo 2027', '≥ 80% (promedio 4)', '≥ 60% (promedio 3)', 'no', 'Visita sorpresa de RRHH con formato firmado (carpetas y procedimientos) y revisión del ERP desde el escritorio', 'Lista de documentos obligatorios y lista de procedimientos escritos de cada área, aprobadas por gerencia en enero. Formato de la visita', 'RRHH en visita sorpresa (el área de RRHH la revisa gerencia)', 'borrador', 'Preguntas 1, 2 y 4: 10 documentos o registros al azar; 5 = 10 de 10, 4 = 9, 3 = 7-8, 2 = 5-6, 1 = 4 o menos. Pregunta 3: 3 documentos al azar; 5 = los 3 en menos de 5 minutos, 4 = los 3 pero alguno se demoró, 3 = 2 de 3, 2 = 1 de 3, 1 = ninguno. Pregunta 5: 5 = ningún error, 4 = uno menor, 3 = dos o tres menores, 2 = uno grave o varios menores, 1 = errores frecuentes. Pregunta 6: un procedimiento escrito al azar, explicado por el jefe y 2 personas del equipo; 5 = los tres como está escrito, 4 = pequeñas diferencias, 3 = solo el jefe lo conoce bien, 2 = nadie lo sigue como está escrito, 1 = no está escrito. La visita la hace Zaray; su área la revisa gerencia. Para Contabilidad, la parte de ERP se mira en Odoo.', 2 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'COMUN' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'comun-equipo', 'competencia', 'Trabajo en equipo', 'Encuesta confidencial a los jefes con los que más trabaja (mínimo 3, escogidos por gerencia) y a gerencia, de 1 a 5 (1 Nunca, 2 Pocas veces, 3 A veces, 4 Casi siempre, 5 Siempre). Promedio de todas las respuestas ÷ 5 × 100. (1) Responde a tiempo lo que mi área le pide. (2) Cumple lo que acuerda con mi área. (3) Comparte la información que mi área necesita, sin que haya que insistirle. (4) Cuando hay un problema entre áreas, busca la solución en lugar de buscar culpables. (5) Respeta las funciones de las otras áreas y no se mete en lo que no le compete.', 25, 0, 'Semestral (junio y noviembre, junto con la encuesta de liderazgo)', 'Primera encuesta: junio 2027', '≥ 80% (promedio 4)', '≥ 60% (promedio 3)', 'no', 'Encuesta confidencial que recoge RRHH entre los jefes, más la calificación de gerencia', 'Definir qué jefes califican a cada jefe (mínimo 3) y el formato de la encuesta', 'Los otros jefes y gerencia (encuesta confidencial)', 'borrador', 'El jefe solo ve el promedio. Un 1 o un 5 exige escribir el caso (fecha y qué pasó), para evitar calificaciones por rabia o amistad.', 3 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'COMUN' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'comun-liderazgo', 'competencia', 'Liderazgo', 'Encuesta al equipo de cada jefe, de 1 a 5 (1 Nunca, 2 Pocas veces, 3 A veces, 4 Casi siempre, 5 Siempre). Promedio de todas las respuestas ÷ 5 × 100. (1) Mi jefe me explica claramente qué tengo que hacer y qué se espera de mí. (2) Mi jefe me dice cómo voy: me corrige cuando me equivoco y me reconoce cuando hago bien las cosas. (3) Mi jefe me trata con respeto. (4) Mi jefe me enseña y me ayuda a aprender cosas nuevas del trabajo. (5) Mi jefe resuelve los problemas del equipo de forma justa, sin preferencias. (6) Mi jefe me escucha cuando tengo un problema o una idea. Pregunta abierta sin calificación: ¿Qué debería mejorar tu jefe?', 25, 0, 'Semestral (junio y noviembre, con los ciclos de RRHH); en los trimestres sin encuesta se usa el último resultado', 'Primera encuesta: junio 2027', '≥ 80% (promedio 4)', '≥ 60% (promedio 3)', 'no', 'Encuesta individual y confidencial que aplica RRHH a cada miembro del equipo', 'Formato de encuesta y lista del equipo de cada jefe. Definir quién encuesta al equipo de RRHH (no puede ser Zaray)', 'El equipo del jefe (encuesta confidencial que aplica RRHH)', 'borrador', 'Confidencial: el jefe solo ve el promedio y los comentarios sin nombre. Mínimo 3 personas por jefe; con menos, no aplica y el 40% se reparte entre las otras tres competencias. Se puede leer en voz alta a quien lo necesite. Siempre las mismas preguntas para comparar entre semestres.', 4 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'COMUN' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'contabilidad-cierre', 'kpi', 'Informes financieros entregados a tiempo y completos', 'Meses en que los EEFF de las dos empresas se entregan completos a más tardar el día 12 del mes siguiente ÷ meses del período, acumulado', 40, NULL, 'Mensual (calificación trimestral)', '2026: entrega irregular; costo de ventas sin registrar en enero, febrero y octubre', '100% (todos los meses al día 12)', 'Ningún mes después del día 15', 'si', 'Fecha de entrega de los EEFF a gerencia (registro simple) y pantalla de EEFF del ERP', 'Acordar cómo se registra la fecha de entrega', NULL, 'borrador', 'Completo = costo de ventas registrado en el mes, compras con centro de costo, inventario contra el ERP con diferencia menor a 3% y bancos conciliados. Si el 12 cae en fin de semana o festivo, se entrega el día hábil anterior.', 1 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'CON' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'contabilidad-saneamiento', 'kpi', 'Saneamiento contable', 'Tres partes: créditos al día en el sistema cada mes, con saldo igual al extracto del banco (40% del KPI) + activos fijos inventariados y registrados con su depreciación a junio (30%) + cuentas depuradas ÷ cuentas a depurar aprobadas por gerencia, a diciembre (30%)', 35, NULL, 'Créditos mensual; activos y depuración por hito', 'Créditos: por revisar. Activos: en 2025 la propiedad, planta y equipo figura fija en $667 M sin depreciación. Depuración: sin lista', 'Créditos al día todos los meses; activos a junio; 100% de cuentas depuradas a diciembre', 'Créditos al día en al menos 10 de 12 meses; activos a julio; 80% de cuentas depuradas', 'parcial', 'Odoo (saldos de obligaciones financieras y activos) contra extractos bancarios e inventario físico de activos', 'Lista de créditos vigentes, inventario físico de activos fijos y lista de cuentas a depurar aprobada por gerencia (a febrero)', NULL, 'borrador', 'La lista de cuentas a depurar la aprueba gerencia, para que no se escojan solo las fáciles.', 2 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'CON' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'contabilidad-renta', 'kpi', 'Reporte quincenal del estado de renta', 'Reportes de estimación del impuesto de renta entregados a tiempo ÷ reportes programados (24 en el año), acumulado', 25, NULL, 'Quincenal (calificación trimestral)', 'No se entrega de forma periódica', '100% a tiempo', '≥ 90%', 'si', 'Fecha de entrega del reporte a gerencia', 'Acordar el formato del reporte y las fechas de entrega', NULL, 'borrador', 'Propuesta de fechas: a más tardar 3 días hábiles después del corte del 15 y del último día de cada mes. Debe incluir utilidad acumulada, renta estimada y anticipos o retenciones a favor.', 3 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'CON' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'ensamble-of-a-tiempo', 'kpi', 'OF entregadas a tiempo', 'OF entregadas a más tardar en su fecha prometida ÷ OF cuya fecha prometida ya venció, acumulado', 60, NULL, 'Semanal (calificación trimestral)', 'Por calcular desde el ERP (OF desde octubre 2026)', '≥ 90%', '≥ 75%', 'si', 'ERP: órdenes de fabricación (fecha prometida) y entregas de OF (fecha de entrega)', 'Sacar la línea base oct-dic 2026 y agregar el registro de faltantes de material', NULL, 'borrador', 'Excepción: OF retrasada por falta de material, solo si el faltante se registró en el ERP el mismo día. Lo ve toda la planta en la reunión semanal.', 1 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'ENS' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'ensamble-calidad', 'kpi', 'Máquinas terminadas con revisión de calidad aprobada', 'Máquinas terminadas con revisión de calidad aprobada en el ERP ÷ máquinas terminadas, acumulado', 40, NULL, 'Semanal (calificación trimestral)', '0% (no se controla calidad)', '100%', '≥ 95%', 'no', 'ERP: revisión de calidad por serial de máquina', 'Crear en el ERP la revisión de calidad por máquina (aplazado por gerencia hasta cerrar los KPIs). Hoy no hay planillas ni números de máquina registrados en el ERP', NULL, 'borrador', 'Se mide sobre máquinas terminadas y no despachadas, porque los números de máquina no están enlazados con las entregas de OF (decisión del 17/11). Empieza por el hábito; en 2028 pasa a reclamos de clientes por calidad.', 2 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'ENS' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'fundicion-merma', 'kpi', 'Merma de hierro', 'Kg perdidos (hierro colado − kg de piezas buenas − vaceadero) ÷ kg de hierro colado, acumulado', 50, NULL, 'Mensual (calificación trimestral)', 'Promedio de diciembre 2026 y enero 2027', 'Reducción frente a la base (porcentaje por definir con la base)', 'No subir frente a la base', 'si', 'ERP: fundidas (hierro colado, vaceadero) y órdenes de moldeo (piezas recogidas); analítica de fundición', 'Sacar la línea base', NULL, 'borrador', 'Se compara contra el período base. Cada kilo de merma es hierro comprado que se pierde.', 1 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'FUN' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'fundicion-no-conformes', 'kpi', 'Piezas con defecto de fundición', 'Piezas con no conformidad (porosidad, rechupes, fisura, inclusiones, dimensión, etc.) ÷ piezas fundidas, acumulado', 50, NULL, 'Mensual (calificación trimestral)', 'Promedio de diciembre 2026 y enero 2027', 'Reducción frente a la base (porcentaje por definir con la base)', 'No subir frente a la base', 'parcial', 'ERP: módulo de no conformidades (calidad) y órdenes de moldeo', 'Confirmar que todas las piezas malas se registran con su motivo y sacar la línea base', NULL, 'borrador', 'Se revisa también por motivo, para saber qué atacar primero. Riesgo: que se dejen de registrar piezas malas para mejorar el número; cruzar con la merma.', 2 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'FUN' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'innovacion-centro-mecanizado', 'kpi', 'Uso del centro de mecanizado', 'Horas del centro de mecanizado produciendo ÷ horas disponibles del turno, acumulado', 50, NULL, 'Mensual (calificación trimestral)', 'Sin registro. La máquina pasa buena parte del tiempo quieta', '≥ 70% (a confirmar con el primer mes medido)', '≥ 50%', 'no', 'ERP: registro de producción con hora de inicio y fin', 'Agregar hora de inicio y fin al registro (mismo cambio que Mecanizados)', NULL, 'borrador', 'Las paradas por mantenimiento con orden aprobada se descuentan de las horas disponibles.', 1 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'IYD' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'innovacion-proyectos', 'kpi', 'Proyectos entregados a tiempo', 'Proyectos entregados completos en su fecha ÷ proyectos cuya fecha ya venció, acumulado. Cada proyecto tiene su propia fecha, dure lo que dure', 50, NULL, 'Mensual (calificación trimestral)', '2026: un solo proceso mejorado, ningún proyecto presentado', '100% a tiempo, con al menos 1 proyecto entregado cada trimestre y mínimo 4 en el año', '≥ 80% a tiempo y mínimo 3 en el año', 'si', 'Plan de proyectos aprobado por gerencia y fecha de entrega de cada entregable', 'Aprobar el plan de proyectos 2027 en enero', NULL, 'borrador', 'Plan aprobado en enero con la lista de proyectos, y para cada uno: entregable concreto (plano, prototipo, proceso documentado), fecha de entrega y ahorro estimado en pesos. Se pueden agregar proyectos durante el año con aprobación de gerencia; desde ese momento cuentan con su fecha. Una fecha solo se puede mover con aprobación de gerencia y antes de que venza. Opción para el primer trimestre: listas de materiales y planos de las 5 máquinas más vendidas.', 2 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'IYD' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'logistica-errores-despacho', 'kpi', 'Despachos con error', 'Despachos con error ÷ total de despachos, acumulado del año', 35, NULL, 'Mensual (calificación trimestral)', 'No existe registro en 2026', '≤ 1%', '≤ 3%', 'no', 'ERP: entregas de órdenes de fabricación + acta de entrega firmada y fotos', 'Definir qué es error (equipo o referencia equivocada, faltante, daño, documento o dirección errada) y agregar la casilla en el ERP. Protocolo de despacho a marzo 2027', NULL, 'borrador', 'Protege la venta a cliente final. Primer trimestre solo se mide.', 1 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'LOG' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'logistica-leadtime', 'kpi', 'Lead time de compras nacionales', 'Promedio de días hábiles entre la requisición (pedido) y la recepción en bodega, acumulado del año', 35, NULL, 'Mensual (calificación trimestral)', 'Estimado por Efraín: local 3-5 días, nacional bajo pedido 8-12 días. Falta el dato real', 'Nacional ≤ 6 días hábiles; local ≤ 2', 'Nacional ≤ 8 días hábiles', 'parcial', 'ERP: pedidos (fecha de creación), órdenes de compra y fecha de recibido. Disponible desde octubre 2026', 'Sacar la línea base real oct-dic 2026 del ERP', NULL, 'borrador', 'Mide contra meta fija. Reduce paradas de planta y fletes expresos.', 2 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'LOG' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'logistica-proveedor-alterno', 'kpi', 'Referencias críticas con proveedor alterno', 'Referencias críticas con proveedor alterno homologado ÷ referencias críticas que hoy tienen un solo proveedor', 30, NULL, 'Trimestral', '0% (no hay alternos homologados)', '≥ 80% a junio 2027', '≥ 60% a junio 2027', 'parcial', 'Base de proveedores unificada del ERP y Odoo; historial de órdenes de compra', 'Armar la lista de referencias con proveedor único y que la apruebe gerencia (feb 2027)', NULL, 'borrador', 'Homologado = cotización vigente y aprobado por taller, no solo un nombre en la lista.', 3 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'LOG' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'mecanizados-insumos', 'kpi', 'Costo de insumos y herramientas por pieza mecanizada', 'Costo de las salidas de almacén a Mecanizados (insertos, brocas, refrigerante, ferretería) ÷ piezas mecanizadas, acumulado del año', 50, NULL, 'Mensual (calificación trimestral)', 'Promedio de diciembre 2026 y enero 2027 (se empieza a registrar desde diciembre)', 'Bajar 10% frente a la base (a confirmar con la base)', 'No subir frente a la base', 'parcial', 'ERP: movimientos de salida a producción (bodega, cantidad y costo) y registro de mecanizado (piezas)', 'Que desde el 1 de diciembre toda salida para Mecanizados pase por el ERP, y costear los insumos que están en $0', NULL, 'borrador', 'Se compara contra el período base. Diciembre puede ser un mes atípico (vacaciones), por eso la base suma enero.', 1 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'MEC' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'mecanizados-tiempos', 'kpi', 'Reducción del tiempo de mecanizado por pieza', 'Tiempo promedio por pieza de las 20 referencias principales en el trimestre ÷ tiempo promedio de esas mismas referencias en el período base. Se compara pieza por pieza para que no influya cuáles se fabricaron', 50, NULL, 'Trimestral', 'Primer período con tiempos registrados (diciembre 2026 o enero 2027, según cuándo esté el campo en el ERP)', 'Reducción por trimestre (porcentaje por definir con la base)', 'No subir frente a la base', 'no', 'ERP: registro de mecanizado con hora de inicio y fin', 'Agregar hora de inicio y fin al registro de mecanizado y empezar a registrar', NULL, 'borrador', 'Riesgos: que los tiempos del período base se registren inflados (verificar con revisiones al azar) y que bajar tiempo dañe la calidad (seguir las piezas defectuosas). Sirve para costear la mano de obra por pieza.', 2 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'MEC' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'rrhh-desempeno', 'kpi', 'Gestión del desempeño', 'Tres hitos: perfiles 22/22 a marzo (40% del KPI) + primer ciclo de evaluación ≥90% en junio (30%) + segundo ciclo ≥90% en noviembre (30%)', 35, NULL, 'Por hito (marzo, junio, noviembre)', '16 de 22 perfiles documentados (72%). Evaluaciones 2026 pendientes en varias áreas', 'Los tres hitos cumplidos a tiempo', 'Perfiles 22/22 a marzo', 'parcial', 'Perfiles: archivo de RRHH. Evaluaciones: registro en el ERP', 'Diseñar el formato de evaluación por área con cada jefe (feb-may 2027)', NULL, 'borrador', 'Una persona cuenta como evaluada solo si: se usó su perfil de cargo e indicadores acordados con el jefe, hubo retroalimentación y quedó registrada en el ERP.', 1 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'RRHH' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'rrhh-rotacion', 'kpi', 'Rotación de personal', 'Retiros acumulados del año ÷ promedio de colaboradores del período × 100. Se compara contra el mismo período de 2026', 35, NULL, 'Mensual (calificación trimestral)', 'Por definir: rotación 2026 (RRHH reporta que bajó 10% vs. 2025)', 'Bajar al menos 10% frente a 2026', 'Por definir con la línea base', 'parcial', 'ERP (contratos y novedades) y registros de RRHH', 'Cifra de rotación 2026 en números; contratos cargados al ERP a febrero 2027', NULL, 'borrador', 'Propuesto por Zaray. Mide a todo el personal.', 2 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'RRHH' ON CONFLICT (area_id, codigo) DO NOTHING;
INSERT INTO public.desempeno_jefes_items (area_id, codigo, tipo, nombre, formula, peso, peso_sin_encuesta, frecuencia, linea_base, meta, minimo, hay_dato, fuente_dato, que_falta, quien_califica, estado, notas, orden) SELECT id, 'rrhh-retencion90', 'kpi', 'Retención a 90 días', 'Contratados que siguen activos a los 90 días ÷ total de contratados (acumulado del año)', 30, NULL, 'Mensual (calificación trimestral)', 'Por definir: dato 2026 a 90 días. Referencia: de 37 ingresos en 2026 siguen 13 (35%)', 'Por definir con la línea base (Zaray propuso 85%, se ve lejana)', 'Por definir', 'parcial', 'Fechas de ingreso y retiro en el ERP', 'Calcular la retención a 90 días de 2026', NULL, 'borrador', 'Mide si se está contratando bien. El tiempo de cobertura de vacantes queda como dato de seguimiento, no como KPI.', 3 FROM public.desempeno_jefes_areas WHERE anio = 2027 AND codigo = 'RRHH' ON CONFLICT (area_id, codigo) DO NOTHING;
