-- ============================================================
-- Datos: plan de evaluación de jefes 2027 (correr después de 2026-11-26_rrhh_plan_jefes.sql)
-- ============================================================
-- Datos iniciales del plan de evaluación de jefes 2027, copiados del registro el 2026-11-26.
-- ON CONFLICT DO NOTHING: si ya existen, no se pisan las ediciones hechas en el ERP.



SELECT a.codigo, count(i.id) FROM public.desempeno_jefes_areas a LEFT JOIN public.desempeno_jefes_items i ON i.area_id = a.id WHERE a.anio = 2027 GROUP BY a.codigo ORDER BY a.codigo;
